    output["users"] = {uid: {"email": u.email} for uid, u in db.users.items()}
    orders = {}
    for oid, o in db.orders.items():
        items = [{"item_id": it.item_id, "product_id": it.product_id, "name": pid_to_name.get(it.product_id, "?")} for it in o.items]
        orders[oid] = {"status": o.status, "user_id": o.user_id, "items": items}
    output["orders"] = orders
    output["ok"] = True
except Exception as e:
    output["ok"] = False
    output["error"] = traceback.format_exc()
with open("retail_dump.json", "w") as f:
